// Year 8 English language, part 2: more Greek and Latin roots (the ones her Greek lessons will
// keep producing), literary and academic vocabulary sets, words easily confused, grammar for
// effect, narrative and descriptive craft, non-fiction forms and hard spellings; narrative voice,
// structure and advanced rhetoric as GCSE-style stretch. Plus 30 more sentence challenges and 17
// more weekly writing pieces, so the course has 36: a school year without repeats.

import { readFileSync } from 'node:fs';
import LANG from './english-lang.mjs';

const PASSAGES = JSON.parse(readFileSync(new URL('./passages.json', import.meta.url), 'utf8'));
const fact = (id, topic, prompt, answer, distractors, explain, extra = {}) => ({ id: `english.lang2.${id}`, topic: `english.lang2-${topic}`, kind: 'fact', prompt, answer, distractors, explain, ...extra });
const mcq = (id, topic, prompt, options, explain, extra = {}) => ({ id: `english.lang2.${id}`, topic: `english.lang2-${topic}`, kind: 'mcq', prompt, options: options.map(([text, correct, feedback]) => ({ text, correct: !!correct, feedback })), explain, ...extra });
const C = { formats: ['choice'] };
const pre = (p) => (p.startsWith('english.') ? p : `english.lang2-${p}`);
const T = (id, title, prereqs, intro, teach, talk, extra = {}) => ({ id: `english.lang2-${id}`, title, kind: 'facts', prereqs: prereqs.map(pre), batch: 5, intro, teach, talk, ...extra });

const topics = [
  T('roots-1', 'Greek roots 2: rule, form, light and stars', ['english.lang-greek-roots'], 'More Greek building blocks: arche (rule), nomos (law), morphe (shape), phos (light), aster (star), kryptos (hidden). Many of them are words you will meet in your Greek lessons.', 'Decode “cryptography” and “autonomy” from their roots.', 'Ask {him} to find a word with “-archy” or “-nomy” in the news and decode it.'),
  T('roots-2', 'Greek prefixes', ['roots-1'], 'Greek prefixes change a word’s meaning at a stroke: eu- (good), dys- (bad), hyper- (over), hypo- (under), syn- (together), pan- (all), meta- (beyond).', 'Explain the difference between “utopia” and “dystopia”.', 'Play “prefix tennis”: one of you names a Greek prefix, the other gives a word that uses it.'),
  T('latin-2', 'More Latin roots', ['english.lang-latin-roots'], 'More Latin roots that run through English: vid (see), mit (send), duc (lead), voc (call), vert (turn), loqu (speak), mort (death), omni (all).', 'Use roots to explain what “loquacious” and “omnivore” mean.', 'Ask {him} how many words {she} can make from “duct” or “vert” in a minute.'),
  T('vocab-2', 'Literary vocabulary', ['english.lang-vocab'], 'Words for describing characters, settings and moods precisely: foreboding, desolate, enigmatic, malevolent, capricious. The right word does the work of a whole sentence.', 'Describe a Greek god using three of today’s words, and justify each.', 'Ask {him} which of today’s words best describes {her} favourite fictional villain.'),
  T('vocab-3', 'Academic vocabulary for essays', ['english.lang-vocab'], 'Essay words help you argue with precision: concede, corroborate, implicit, nuanced, plausible, substantiate. They mark the difference between a good answer and an excellent one.', 'Explain the difference between “explicit” and “implicit”, with an example from a text.', 'Ask {him} to use “concede” and “however” in one spoken sentence about a family argument.'),
  T('confused', 'Words easily confused', ['english.lang-spelling'], 'Affect or effect? Imply or infer? Fewer or less? Some pairs trip up adult writers. Knowing them is a quick win in every piece of writing.', 'Explain the difference between “imply” and “infer”.', 'Spot a “less” that should be “fewer” on a supermarket sign together.'),
  T('grammar-3', 'Grammar for effect', ['english.lang-clauses', 'english.lang-relative'], 'Grammar is a toolkit for meaning: noun phrases that pack in detail, apposition, non-finite clauses, inversion, minor sentences and lists with or without “and”.', 'Explain the effect of starting a sentence with “Into the darkness crept…”.', 'Read a paragraph from {her} book together and find one sentence built for effect.'),
  T('craft-2', 'Narrative techniques', ['english.lang-craft'], 'Writers plan effects across a whole story: pathetic fallacy, motifs, foreshadowing, flashbacks, dramatic irony and cyclical structure. Homer used several of them nearly three thousand years ago.', 'Explain what foreshadowing is and give an example from a myth you know.', 'Ask {him} which technique the last film you watched together used.'),
  T('description', 'Writing description', ['craft-2'], 'Good description is designed like a film: wide shot, zoom in, one telling detail. Precise nouns and verbs beat strings of adjectives, and every sense counts.', 'Explain why “the oak groaned” is stronger than “the big old tree made a noise”.', 'Describe the view from a window together using one sound, one smell and one texture.'),
  T('nonfiction', 'Non-fiction forms', ['english.lang-rhetoric'], 'Articles, letters, speeches, reviews and reports each have conventions. Exam tasks reward the right form for the audience and purpose.', 'Explain when you would sign a letter “Yours faithfully” rather than “Yours sincerely”.', 'Look at a newspaper together and find the headline, standfirst and byline.'),
  T('spelling-2', 'Hard spellings', ['english.lang-spelling'], 'Words that catch out confident writers: conscientious, supersede, minuscule, manoeuvre. Each has a trick.', 'Explain the trick for spelling “supersede”.', 'Test {him} on three of today’s words; then let {him} test you.'),
  // stretch: GCSE tasters
  T('voice', 'Narrative voice and irony', ['craft-2'], 'At GCSE you analyse how a story is told: who sees, who speaks, and how far we can trust them. Irony, free indirect style and epistolary form are the advanced tools.', 'Explain the difference between dramatic irony and situational irony.', 'Ask {him} whether the narrator of {her} current book can be trusted, and why.', { tier: 'stretch' }),
  T('structure', 'Analysing structure', ['craft-2', 'english.lang-analysis'], 'Structure questions ask why the writer arranged the text this way: shifts in focus, withheld information, changes in pace, an ending that echoes the opening.', 'Explain one structural feature in the opening of a story you know.', 'After a film, ask {him} why it began where it did.', { tier: 'stretch' }),
  T('rhetoric-2', 'Advanced rhetoric', ['english.lang-rhetoric'], 'The Greeks taught rhetoric as an art. Beyond the rule of three: chiasmus, epistrophe, hypophora, litotes, zeugma, procatalepsis. Recognise them in great speeches and use them in your own.', 'Explain chiasmus using a famous example.', 'Listen to a short speech together and count the rhetorical devices.', { tier: 'stretch' }),
];

