  'sp2.supersede': { hook: 'Supersede comes from Latin sedere, to sit: to sit above. It is the only common word ending -sede.' },
  'sp2.bureaucracy': { hook: 'Bureau is French for desk: bureaucracy is rule by people at desks.' },
